/**
 * 符号表
 */

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        _type:"normal",

    },

    Init(idx,node){
        this._super(idx,node)
    },

    setSymType(type){
        this._type = type;
    },

    // 初始展示时的随机节点（不含宝石图标）
    ShowRandomSymbolFirst(){
        let cfg = cc.vv.gameData.getGameCfg()
        let randIdx = Global.random(1,cfg.randomSymbolsFirst.length)
        let randVal = cfg.randomSymbolsFirst[randIdx-1]
        this.ShowById(randVal)
    },

    ShowRandomSymbol(){
        this._super();

        if(this._id === 4){
            let num = Global.random(1,5) * cc.vv.gameData.GetTotalBet();
            this.setNum(num);
        }

    },

    ShowById(id,data){

        if(id === 4 && data){
            if( data.type === "coin") {
                this.setNum(data.num);
            } else if(data.type === "pool"){
                if(data.num === 1){
                    id = 401;
                } else if (data.num === 2){
                    id = 402;
                } else if (data.num === 3){
                    id = 403;
                } else if (data.num === 4){
                    id = 404;
                }
                this.setNum();
            }
        } else {
            this.setNum();
        }

        if(this._type === "bonus"){
            this._id = id
            this._data = data
            this._state = "normal";

            if(this._showNode){
                this._showNode.active = false
            }
            let cfg = cc.vv.gameData.getGameCfg()
            if(cfg.symbol[id] && cfg.symbol[id].bonus_node){
                this._showNode = cc.find(cfg.symbol[id].bonus_node,this.node)
                this._showNode.active = true
            }
        } else {
            this._super(id,data);
        }
    },

    StartMove(){
        this._super();

        // this.hideTextAndPool();
        // this.setMaskVisible(true);
    },

    setNum(num){
        let lbl = cc.find("lbl_num",this.node);
        if (num){
            let font = null;
            let nVal = cc.vv.gameData.GetTotalBet()

            if(num < 5*nVal){
                font = cc.vv.gameData.GetFontByName("theme125_zzb");
            } else {
                font = cc.vv.gameData.GetFontByName("theme125_zz");
            }

            lbl.active = true;
            lbl.getComponent(cc.Label).font = font;
            lbl.getComponent(cc.Label).string = Global.formatNumShort(num);
        }else {
            lbl.active = false;
            lbl.getComponent(cc.Label).string = "";
        }
    },

    setBonusIndex(index){
        this._bonusIndex = index
    },

    // 宝石图标上升时动画
    playBonusWin(bShow){
        let node = cc.find("w4_win",this.node);
        let list = cc.vv.gameData.getGameCfg().gemIdList;
        if(bShow && (list.includes(this._id))){
            node.active = true;
            node.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
        }else {
            node.active = false;
        }
    },

    // 宝石图标上升后的动画
    playBonusAnim(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].bonus_ani){
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            if(cfg.symbol[id].bonus_ani.name != ""){
                // this.node.zIndex = cfg.symbol[id].bonus_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].bonus_ani.name,true)
                }
            }
        }
    },

})
