cc.Class({
    extends: require("LMSlots_PauseUI_Base"),

    properties: {
        _exitCallBack:null,

        _curTimes:3,   // 当前剩余次数
        _curUnlockNum:0,    // 当前解锁的宝石个数



        _reels:[],  //卷轴脚本对象
        _shelterList:[],    // 横条遮罩
        _bonusPoolList:[],   // 奖池节点
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this.initBonusNode();

        this._topScript = cc.vv.gameData.GetTopScript();
        this._bottomScript = cc.vv.gameData.GetBottomScript();

        this._cfg = cc.vv.gameData.getGameCfg();
        this._col = this._cfg.bonus_col;
        this._row = this._cfg.bonus_row;

        this.createReels(this._col, this._row);


        this.initBonusUI();

    },

    //创建卷轴
    createReels:function(col, row){
        let reelCmp = this._cfg.scripts.Reels;
        for (let i = 0; i < col; i++) {
            let node = cc.find("reels/reel" + (i+1),this._bonus_slots);
            let scp = node.addComponent("LegendOfJoanOfArc_BonusReel");
            scp.Init(i,1,row,this._topAniNode);
            this._reels.push(scp)

        }
    },


    // 初始化节点
    initBonusNode(){

        // this._bg_bonus = cc.find("safe_node/spr_bg_bonus", this.node);
        this._normal_slots = cc.find("safe_node/slots", this.node);
        this._bonus_slots = cc.find("safe_node/bonus_slots", this.node);
        this._prizePool = cc.find('Canvas/safe_node/LMSlots_PrizePool_1')

        this._topAniNode = cc.find("top_ani",this._bonus_slots);
        this._gemTopNode = cc.find("top_gem",this._bonus_slots);

        this._mask_frame = cc.find("mask_frame", this._bonus_slots);
        this._frame_top = cc.find("frame_top", this._bonus_slots);
        this._node_reels = cc.find("reels", this._bonus_slots);
        this._node_bonus_win = cc.find("node_bonus_win", this._bonus_slots);

        this._frame_bg = cc.find("bg", this._mask_frame);
        this._node_col = cc.find("node_col", this._mask_frame);
        this._node_row_left = cc.find("node_row_left", this._mask_frame);
        this._node_row_right = cc.find("node_row_right", this._mask_frame);
        this._bonus_bg = cc.find("bonus_bg", this._mask_frame);

        this._spr_left = cc.find("spr_left", this._frame_top);
        this._spr_right = cc.find("spr_right", this._frame_top);
        this._spr_up = cc.find("spr_up", this._frame_top);
        this._spr_up_0 = cc.find("spr_up_0", this._frame_top);
        this._par_left = cc.find("par_left", this._frame_top);
        this._par_right = cc.find("par_right", this._frame_top);
        this._node_tit = cc.find("node_tit", this._frame_top);

        this._shelterList.push(cc.find("shelter_1", this._frame_top));
        this._shelterList.push(cc.find("shelter_2", this._frame_top));
        this._shelterList.push(cc.find("shelter_3", this._frame_top));
        this._shelterList.push(cc.find("shelter_4", this._frame_top));

    },

    // 初始化节点状态
    initBonusUI(){
        // this._bg_bonus.active = false;
        this._normal_slots.active = true;
        this._bonus_slots.active = false;

        this._frame_bg.getChildByName("spr").active = false;

        this.setLineState(this._node_col, false);
        this.setLineState(this._node_row_left, false);
        this.setLineState(this._node_row_right, false);

        this._spr_up.active = false;
        this._spr_up_0.active = false;

        this._bonus_bg.active = false;
        this._par_left.active = false;
        this._par_right.active = false;
        this._node_tit.active = false;
        this._node_reels.active = false;
        this._node_bonus_win.active = false;

        for(let i = 0; i < this._shelterList.length; i++){
            this._shelterList[i].active = false;
        }
    },

    setLineState(parentNode, bShow){
        for (let i = 0; i < parentNode.childrenCount; i++){
            parentNode.children[i].active = bShow;
        }
    },

    // 触发
    async triBonusGame(success){
        this._exitCallBack = success;

        Global.SlotsSoundMgr.playBgm('bonus_bgm')

        await this.playTriAnim();

    },

    // 触发动画
    playTriAnim(){
        return new Promise(async (sucess, failed)=> {

            // 1.初始大小显示
            // this._bg_bonus.active = true;
            this._normal_slots.active = false;
            this._bonus_slots.active = true;
            this._frame_bg.y = -383;
            this._spr_left.y = -383;
            this._spr_right.y = -383;
            this._spr_up_0.active = true;
            this._spr_up_0.opacity = 255;
            this.lockJackpot(this._bonusPoolList);

            await this.awaitTime(0.5);

            Global.SlotsSoundMgr.playEffect("reel_change");

            // 2.顶层条渐隐消失
            let awaitT1 = 0.5;
            cc.tween(this._spr_up_0).to(awaitT1, {opacity: 0}).start();
            await this.awaitTime(awaitT1);

            // 3.背景、左右框上长到指定位置
            let awaitT2 = 0.8;
            cc.tween(this._frame_bg).to(awaitT2, {position:cc.v2(0, 0)}).start();
            cc.tween(this._spr_left).to(awaitT2, {position:cc.v2(this._spr_left.x, 0)}).start();
            cc.tween(this._spr_right).to(awaitT2, {position:cc.v2(this._spr_right.x, 0)}).start();
            await this.awaitTime(awaitT2);

            // 4.顶层条显示，同时背景变更黑
            let awaitT3 = 0.4;
            this._spr_up.active = true;
            this._spr_up.opacity = 0;
            cc.tween(this._spr_up).to(awaitT3, {opacity: 255}).start();
            let spr_bg = this._frame_bg.getChildByName("spr");
            spr_bg.active = true;
            spr_bg.opacity = 0;
            cc.tween(spr_bg).to(awaitT3, {opacity: 155}).start();
            await this.awaitTime(awaitT3);

            // 5.竖条隔断上长到顶部，底部从中间长到两头 （同时）
            let awaitT4 = 1.4;
            for(let i = 0; i < this._node_col.childrenCount; i++){
                let node = this._node_col.children[i];
                node.active = true;
                node.y = -456;
                if(node.name === "par"){
                    node.getComponent(cc.ParticleSystem).resetSystem();
                }
                cc.tween(node).to(awaitT4, {position:cc.v2(node.x,456)})
                    .call(()=>{
                        if(node.name === "par"){node.active = false;}})
                    .start();
            }

            this._par_left.active = true;
            this._par_left.position = cc.v2(0,-460);
            this._par_left.getComponent(cc.ParticleSystem).resetSystem();
            this._par_right.active = true;
            this._par_right.position = cc.v2(0,-460);
            this._par_right.getComponent(cc.ParticleSystem).resetSystem();
            cc.tween(this._par_left).to(awaitT4, {position:cc.v2(-340,-460)}).start();
            cc.tween(this._par_right).to(awaitT4, {position:cc.v2(340,-460)}).start();

            await this.awaitTime(awaitT4);

            // 6.246行从左往右，1357行从右往左，左右两列长到顶（同时）
            let awaitT5 = 1.4;
            for(let i = 0; i < this._node_row_left.childrenCount; i++){
                let node = this._node_row_left.children[i];
                node.active = true;
                node.x = -335;
                if(node.name === "par"){
                    node.getComponent(cc.ParticleSystem).resetSystem();
                }
                cc.tween(node).to(awaitT5, {position:cc.v2(335,node.y)})
                    .call(()=>{
                        if(node.name === "par"){node.active = false;}})
                    .start();
            }
            for(let i = 0; i < this._node_row_right.childrenCount; i++){
                let node = this._node_row_right.children[i];
                node.active = true;
                node.x = 335;
                if(node.name === "par"){
                    node.getComponent(cc.ParticleSystem).resetSystem();
                }
                cc.tween(node).to(awaitT5, {position:cc.v2(-335,node.y)})
                    .call(()=>{
                        if(node.name === "par"){node.active = false;}})
                    .start();
            }
            cc.tween(this._par_left).to(awaitT5, {position:cc.v2(-335,460)}).start();
            cc.tween(this._par_right).to(awaitT5, {position:cc.v2(335,460)}).start();

            await this.awaitTime(awaitT5);

            // 7.顶部从两侧到中间
            let awaitT6 = 0.7;
            cc.tween(this._par_left).to(awaitT6, {position:cc.v2(0,460)})
                .call(()=>{this._par_left.active = false;})
                .start();
            cc.tween(this._par_right).to(awaitT6, {position:cc.v2(0,460)})
                .call(()=>{this._par_right.active = false;})
                .start();
            await this.awaitTime(awaitT6);

            // 8.3spins 弹出，背景、所有reels显示
            let awaitT7 = 0.5;
            this._node_tit.active = true;
            this._node_tit.setScale(0);
            Global.SlotsSoundMgr.playEffect("bonus_respin_board");
            cc.tween(this._node_tit).to(awaitT7, {scale:1}, { easing: 'backOut'}).start()
            this._curTimes = 3;
            this.setTitleNum(this._curTimes);

            this._bonus_bg.active = true;

            this._node_reels.active = true;
            this.initAllSymbol(true);

            await this.awaitTime(0.5);

            // 9.4个锁条从上往下依次出现
            let bonusUnlockList = cc.vv.gameData.getGameCfg().bonusUnlockList;
            for (let i = 0; i < this._shelterList.length; i++){
                if(this._curUnlockNum < bonusUnlockList[i]){
                    Global.SlotsSoundMgr.playEffect("reel_lock");
                    this._shelterList[i].active = true;
                    cc.find("spr_lock/lbl_num",this._shelterList[i]).getComponent(cc.Label).string = bonusUnlockList[i] - this._curUnlockNum;
                    // this._shelterList[i].setScale(0.2);
                    // cc.tween(this._shelterList[i]).to(0.3,{scale:1},{easing:'backOut'}).start();
                    await this.awaitTime(0.3);
                }
            }

            // 10.宝石节点爆炸动画，显示到顶层，播放动画
            let awaitT9 = 1;
            let info = cc.vv.gameData.GetBonusInfo();
            Global.SlotsSoundMgr.playEffect("bonus_coin_land");
            for (let key in info){
                let idx = Number(key.substring("idx_".length));
                idx = idx+20;

                let col = this.getColByIdx(idx);
                let row = this.getRowByIdx(idx);
                let symscp = this.cloneSymToTop(row,col);
                symscp.node.active = true;
                symscp.playBonusWin(true);
                symscp.playBonusAnim();
            }
            await this.awaitTime(awaitT9)

            // 11.弹出press按钮,点击press,面板收回，开始旋转
            await cc.vv.gameData.GetPopupScript().showBonusPress();

            // 12.设置当前为bonus游戏，并开始旋转
            cc.vv.gameData.SetIsBonusGame(true);
            this.sendNextRound();

            sucess();
        })
    },


    // 断线
    async enterBonusGame(success){
        this._exitCallBack = success;

        Global.SlotsSoundMgr.playBgm('bonus_bgm')

        this.showEnterState();

        await this.awaitTime(2);

        cc.vv.gameData.SetIsBonusGame(true);
        this.sendNextRound();
    },

    showEnterState(){
        // 显示所有节点状态
        // this._bg_bonus.active = true;
        this._normal_slots.active = false;
        this._bonus_slots.active = true;
        this._spr_left.position = cc.v2(this._spr_left.x,0);
        this._spr_right.position = cc.v2( this._spr_right.x,0);
        this._spr_up.active = true;
        this._spr_up.opacity = 255;
        this.lockJackpot(this._bonusPoolList)

        for(let i = 0; i < this._node_col.childrenCount; i++) {
            if(this._node_col.children[i].name === "par"){
                this._node_col.children[i].active = false;
            }else {
                this._node_col.children[i].active = true;
                this._node_col.children[i].position = cc.v2(this._node_col.children[i].x, 375);
            }
        }
        for(let i = 0; i < this._node_row_left.childrenCount; i++) {
            if(this._node_row_left.children[i].name === "par"){
                this._node_row_left.children[i].active = false;
            }else {
                this._node_row_left.children[i].active = true;
                this._node_row_left.children[i].position = cc.v2(329, this._node_row_left.children[i].y);
            }
        }
        for(let i = 0; i < this._node_row_right.childrenCount; i++) {
            if(this._node_row_right.children[i].name === "par"){
                this._node_row_right.children[i].active = false;
            }else {
                this._node_row_right.children[i].active = true;
                this._node_row_right.children[i].position = cc.v2(-329, this._node_row_right.children[i].y);
            }
        }

        this._node_tit.active = true;
        this._node_tit.setScale(1);
        this._curTimes = cc.vv.gameData.GetBonusRestNum();
        this.setTitleNum(this._curTimes);

        this._bonus_bg.active = true;
        this._node_reels.active = true;
        this.initAllSymbol(false);

        // 显示遮罩层状态
        let bonusUnlockList = cc.vv.gameData.getGameCfg().bonusUnlockList;
        for (let i = 0; i < this._shelterList.length; i++){
            if(this._curUnlockNum < bonusUnlockList[i]){
                this._shelterList[i].active = true;
                cc.find("spr_lock/lbl_num",this._shelterList[i]).getComponent(cc.Label).string = bonusUnlockList[i] - this._curUnlockNum;
            } else {
                this._shelterList[i].active = false;
            }
        }

        // 显示宝石状态
        let info = cc.vv.gameData.GetBonusInfo();
        for (let key in info){
            let idx = Number(key.substring("idx_".length));

            let col = this.getColByIdx(idx);
            let row = this.getRowByIdx(idx);
            let symscp = this.cloneSymToTop(row,col);
            symscp.node.active = true;
            symscp.playBonusWin(true);
            symscp.playBonusAnim();
        }
    },

    exitBonusGame(){
        this.initBonusUI();
        cc.vv.gameData.SetIsBonusGame(false);

        this._gemTopNode.destroyAllChildren();
    },

    // 设置奖池节点
    initPoolList(){
        for(let i = 0; i < this._bonusPoolList.length; i++){
            let pool = cc.vv.gameData.GetBonusPool();
            cc.find("lbl_num",this._bonusPoolList[i]).getComponent(cc.Label).string = Global.FormatNumToComma(pool[i]);
        }
    },

    // 设置标题次数
    setTitleNum(num){
        let lbl_remain = cc.find("lbl_remain",this._node_tit);

        // cc.log("     num:",num)
        if(num > 0){
            lbl_remain.active = true;
            lbl_remain.getComponent(cc.Label).string = num;
        }else {
            lbl_remain.active = false;
        }
        cc.find("spr_spins",this._node_tit).active = num > 1;
        cc.find("spr_spin",this._node_tit).active = num === 1;
        cc.find("spr_last",this._node_tit).active = num === 0;
        cc.find("spr_complete",this._node_tit).active = num < 0;

        let spine = cc.find("spine",this._node_tit);
        if (this._curTimes < num){
            spine.active = true;
            spine.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
        }else {
            spine.active = false;
        }

        this._curTimes = num;
    },

    // 初始展示的所有symbol
    initAllSymbol(isChange){
        let info = cc.vv.gameData.GetBonusInfo()
        let reelsData = this.creatReelData(info, isChange);

        this._curUnlockNum = 0
        for(let i = 0; i < this._col*this._row; i++){
            let symbol = this.GetSymbolByIdx(i+1);

            if(reelsData[i].sid === 14){
                let cfg = cc.vv.gameData.getGameCfg()
                let randIdx = Global.random(1,cfg.randomSymbolsFirst.length)
                reelsData[i].sid = cfg.randomSymbolsFirst[randIdx-1]
            } else {
                if(reelsData[i].data && reelsData[i].data.unlock){
                    this._curUnlockNum += 1;
                }
            }

            symbol.ShowById(reelsData[i].sid, reelsData[i].data)
        }
        // cc.log("init this._curUnlockNum:",this._curUnlockNum)
    },

    // 将宝石节点克隆到top层
    cloneSymToTop(nRow,nCol){
        let cfg = cc.vv.gameData.getGameCfg()
        let symScp = cfg.scripts.Symbols
        let showNode = cc.find(cc.js.formatStr("top_Gem_%s_%s",nRow,nCol),this._gemTopNode);
        if(showNode){ //如果已经存在就直接显示
            showNode.active = true

            return showNode.getComponent(symScp)
        }
        else{
            let reel = this._reels[nCol]
            let symbol = reel.GetSymbolByRow(nRow)
            if(symbol){
                let wordPos = symbol.node.convertToWorldSpaceAR(cc.v2(0.0));
                let newNode = cc.instantiate(symbol.node)
                newNode.parent = this._gemTopNode
                newNode.name = cc.js.formatStr("top_Gem_%s_%s",nRow,nCol)
                newNode.position = this._topAniNode.convertToNodeSpaceAR(wordPos)
                return newNode.getComponent(symScp)
            }
        }
    },

    getSymbolTopAni(nRow,nCol){
        let cfg = cc.vv.gameData.getGameCfg()
        let symScp = cfg.scripts.Symbols
        let showNode = cc.find(cc.js.formatStr("top_Gem_%s_%s",nRow,nCol),this._gemTopNode);
        if(showNode){ //如果已经存在就直接显示
            showNode.active = true

            return showNode.getComponent(symScp)
        }
        return  null
    },


    creatReelData(info, isChange){
        let reelData = [];
        for (let i = 0; i < this._col*this._row; i++) {
            let info = {};
            info.sid = 14;
            info.data = {};
            reelData.push(info)
        }

        for (let key in info){
            let idx = Number(key.substring("idx_".length));
            if(isChange){
                idx = idx + 20
            }
            reelData[idx-1].sid = 4;
            reelData[idx-1].data=info[key];
        }

        return reelData;
    },



    //点击旋转按钮调用
    StartMove:function(){
        this._bStopRightnow = null
        this._gameInfo = null

        //top状态更新
        this._topScript.StartMove()

        //清理数据
        // cc.vv.gameData.ClearOneRoundData()

        //每列转起来
        this.MoveReels(this._reels)

        //设置停止时间
        //就是从开始旋转，如果多少秒会开始停止
        this._stopTime = this.GetStopTime()

        this._curTimes -= 1;
        this.setTitleNum(this._curTimes);
        Global.SlotsSoundMgr.playEffect("bonus_remaining");
    },

    //实际旋转起来的列，有时候需要1，2，4列转，
    //即最后停止下来的不是最后一列的序号，所以需要记录最后一列的序号
    //arry=[this._reels[0],this._reels[1],this._reels[4]]
    MoveReels:function(arry){
        this.moveReelLastIdx = -1
        for(let i = 0; i < arry.length; i++){
            let item = arry[i]
            item.StartMove()
            let idx = item.GetReelIdx()
            if(idx> this.moveReelLastIdx){
                this.moveReelLastIdx = idx
            }
        }
    },


    //点击停止按钮调用
    StopMove:function(){
        this._bStopRightnow = true
        this._bottomScript.ShowBtnsByState("moveing_1")

        this._stopTime = -1
        for(let i = 0; i < this._reels.length; i++ ){
            let item = this._reels[i]
            let reelStopInterv = 0 //立即停止
            item.StopMove(reelStopInterv)
            item.StopMoveRightNow()
        }
    },


    //收到旋转结果
    //gameData模块收到数据后，转发到此处
    onMsgSpine:function(msg){
        this._gameInfo = msg
        let cards = msg.resultCards
        this.SetSlotsResult(cards)
    },

    //处理结果给reel设置结果
    SetSlotsResult:function(cards){
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col;
        let reelResults = [];
        for(let i = 0;i < cards.length; i++){
            let row = Math.floor(i / acRow);
            let col = i % this._col;
            //配置中有没有这个元素
            if(this._cfg.symbol[cards[i]]){
                let res = {};
                res.sid = cards[i]; //符号id

                if(res.sid === 14){
                    let cfg = cc.vv.gameData.getGameCfg()
                    let randIdx = Global.random(1,cfg.randomSymbolsFirst.length)
                    res.sid = cfg.randomSymbolsFirst[randIdx-1]
                }

                let infoData = cc.vv.gameData.GetBonusInfo();
                for (let key in infoData){
                    let idx = Number(key.substring("idx_".length));
                    if(idx === i+1){
                        res.data = infoData[key];
                    }
                }

                if(!reelResults[col]) reelResults[col] = [];
                reelResults[col].unshift(res);
            }
        }

        for(let i = 0; i < this._reels.length; i++){
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    // 单列停止
    OnReelBounsActionEnd(colIdx){
        for(let row = 0; row < this._row; row++){
            let syc = this.getSymbolTopAni(row, colIdx);
            if(syc ){

            }else {
                let symScp = this._reels[colIdx].GetSymbolByRow(row);

                if (this._cfg.gemIdList.includes(symScp.GetShowId())){
                    if(symScp.GetShowId() === 4){
                        Global.SlotsSoundMgr.playEffect("bonus_coin_land");
                    } else {
                        Global.SlotsSoundMgr.playEffect("bonus_coin_effect");
                    }


                    let symscp = this.cloneSymToTop(row, colIdx);
                    symscp.node.active = true;
                    symscp.playBonusWin(true);
                    symscp.playBonusAnim();

                    if(symscp.GetData() && symscp.GetData().unlock){
                        this._curUnlockNum += 1;
                        // cc.log("stop this._curUnlockNum:"+this._curUnlockNum+"    col:",colIdx)
                    }
                }
            }
        }

        if(!this._bStopRightnow){
            this.hideShelter(colIdx);
        }
    },

    //全部列都停止了
    //处理停下后的中奖情况，这里多数情况需要根据自己的逻辑来处理
    async OnSpinEnd(){

        // await this.awaitTime(2);

        let restNum = cc.vv.gameData.GetBonusRestNum();
        this.setTitleNum(restNum);
        if(restNum === 3){
            Global.SlotsSoundMgr.playEffect("bonus_remainingReset");
        }

        await this.hideShelter();

        if(restNum === 0){
            await this.playCompleteAnim();

            //4.切屏
            cc.vv.gameData.GetPopupScript().playBonusQpAnim();
            await this.awaitTime(1)

            this.exitBonusGame();
            this._prizePool.active = true;
            await this.awaitTime(1)

            if(this._exitCallBack){
                this._exitCallBack();
            }

            cc.vv.gameData.GetSlotsScript().playGameBgm();

        } else {
            await this.awaitTime(1);

            this.sendNextRound();
        }

    },

    // 隐藏遮罩条
    hideShelter(colIdx){
        return new Promise(async (sucess, failed)=> {
            let bonusUnlockList = cc.vv.gameData.getGameCfg().bonusUnlockList;

            for (let i = this._shelterList.length - 1; i >= 0; i--){
                // cc.log("this._curUnlockNum:",this._curUnlockNum)
                if(this._curUnlockNum >= bonusUnlockList[i]){
                    if(this._shelterList[i].active){
                        Global.SlotsSoundMgr.playEffect("breakup");
                        let self = this;
                        this._shelterList[i].active = false;
                        let spine = cc.find("unlock_"+i,this._frame_top);
                        spine.active = true;
                        spine.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
                        spine.getComponent(sp.Skeleton).setCompleteListener(()=>{

                            spine.active = false
                        });

                        for (let col = 0; col < this._col; col++){
                            let syc = this.getSymbolTopAni(7-i, col);
                            // if(syc && syc.GetData()){
                                // cc.log("syc.GetData().unlock:",syc.GetData().unlock);
                            // }

                            if (syc && syc.GetData() && !syc.GetData().unlock){
                                syc.GetData().unlock = true;

                                // if(col < colIdx){
                                    this._curUnlockNum += 1;
                                    // cc.log("change this._curUnlockNum:",this._curUnlockNum)
                                // }
                            }
                        }
                    }
                }else {
                    cc.find("spr_lock/lbl_num",this._shelterList[i]).getComponent(cc.Label).string = bonusUnlockList[i] - this._curUnlockNum;
                }
            }
            sucess()
        })
    },

    // 播放完成动画
    playCompleteAnim(){
        return new Promise(async (sucess, failed)=> {
            //1.顶部横条显示 complete
            this.setTitleNum(-1);
            Global.SlotsSoundMgr.playEffect("normal_respin_end");
            await this.awaitTime(2);
            this._node_tit.active = false;

            //2.显示赢钱框，里面金币为"", 同时开始一个一个赢钱结果，第一个飞到赢钱框时，奖池节点隐藏
            // Global.SlotsSoundMgr.playEffect("bonus_respin_board");
            this._node_bonus_win.active = true;
            let lbl = this._node_bonus_win.getChildByName("lbl_win");
            let spine_kuang = this._node_bonus_win.getChildByName("spine_kuang");
            let spine_flyFire = this._node_bonus_win.getChildByName("spine_flyFire");
            let spine_fire = this._node_bonus_win.getChildByName("spine_fire");
            let spr_jp = this._node_bonus_win.getChildByName("spr_jp");
            lbl.getComponent(cc.Label).string = "";
            spine_flyFire.active = false;
            spine_fire.active = false;
            spr_jp.active = false;

            this._prizePool.active = false;
            this.resetJackpot();

            let allCoin = 0;
            let startWin = cc.vv.gameData.GetBottomScript().getCurrentWin();
            //（赢钱结果）："coin":金币直接展示  "pool" 金币滚动，显示奖池节点
            for(let col = 0; col < this._col; col++){
                for(let row = this._row-1; row >= 0; row--){
                    let syc = this.getSymbolTopAni(row, col);
                    if(syc){
                        let data = syc.GetData();
                        if(data && data.unlock){

                            let startPos = this._node_bonus_win.convertToNodeSpaceAR(syc.node.convertToWorldSpaceAR(cc.v2(0,0)));
                            spine_flyFire.active = true;
                            spine_flyFire.position = startPos;
                            spine_flyFire.getComponent(sp.Skeleton).setAnimation(0,"animation",false);

                            syc.node.destroy();
                            cc.tween(spine_flyFire)
                                .to(0.3,{position:cc.v2(0,-20)})
                                .start()

                            await this.awaitTime(0.3);
                            spine_fire.active = true;
                            spine_fire.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
                            if(data.type === "coin"){
                                Global.SlotsSoundMgr.playEffect("coin_respin_fly");
                                allCoin += data.num;
                                lbl.getComponent(cc.Label).string = Global.formatNumShort(allCoin);
                                spine_kuang.active = true;
                                spine_kuang.getComponent(sp.Skeleton).setAnimation(0,"animation1", false);
                            } else if(data.type === "pool"){
                                Global.SlotsSoundMgr.playEffect("coin_respin_fly_jp");
                                Global.SlotsSoundMgr.playEffect("bell");
                                let pool = cc.vv.gameData.GetBonusPool()
                                Global.doRoallNumEff(lbl,allCoin,allCoin+pool[data.num-1], 0.8,null,null,0,true);
                                spr_jp.active = true;
                                spr_jp.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("baseImg").getSpriteFrame("jp"+(5-data.num)+"_1");
                                allCoin += pool[data.num-1];

                                spine_kuang.active = true;
                                spine_kuang.getComponent(sp.Skeleton).setAnimation(0,"animation2", false);

                                await this.awaitTime(0.2);
                            }

                            cc.vv.gameData.GetBottomScript().SetWin(allCoin+startWin);
                            await this.awaitTime(0.7);
                            spr_jp.active = false;
                        }
                    }
                }
            }

            //3.赢钱奖励
            let nWin = cc.vv.gameData.GetBonusWinCoin();
            await new Promise((sucess, failed)=>{

                // cc.vv.gameData.AddCoin(nWin);
                cc.vv.gameData.GetSlotsScript().ShowBottomWin(nWin,nWin,true,sucess)
            });

            sucess()
        })
    },


    // 发送下一次旋转请求
    sendNextRound(){
        cc.vv.gameData.GetBottomScript().SendSpinReq();
    },

    //自动停止时间
    //不配的话，就3s后停止
    GetStopTime:function(){
        return this._cfg.auto_stop_time || 1
    },

    //设置旋转停止时间
    //如果需要列不停止，可以将时间设置的很大。
    SetStopTime:function(nVal){
        this._stopTime = nVal
    },

    //每列停止时间间隔 = 每列的停止间隔 + 每列的回弹时间
    //reelIdx:0开始
    GetReelStopInter:function(reelIdx){
        let nIter = this._cfg.reelStopInter || 0.6
        return reelIdx*nIter
    },

    getColByIdx(idx){
        return (idx - 1) % this._col;
    },

    getRowByIdx(idx){
        return this._row - Math.floor((idx -1)/this._col) -1;
    },

    //根据服务端序号获取本地的symbol
    GetSymbolByIdx:function(idx){
        let col = (idx - 1) % this._col
        let row = this._row - Math.floor((idx -1)/this._col) -1
        return this._reels[col].GetSymbolByRow(row)
    },

    //获取最后一个停下来的列序号
    GetLastStopReelIdx:function(){
        return this.moveReelLastIdx
    },
    update (dt) {
        if(this._stopTime > 0){
            this._stopTime = this._stopTime - dt
            if(this._stopTime <= 0 ){ //空转时间到了
                this._bottomScript.ShowBtnsByState("moveing_2")
                //倒计时完，设置一次
                for(let i = 0; i < this._reels.length; i++ ){
                    let item = this._reels[i]
                    let reelStopInterv = this.GetReelStopInter(i)
                    item.StopMove(reelStopInterv)
                }

            }
        }


    },

    //奖池锁定(停止滚动)
    lockJackpot(poolList){
        let prizepool = cc.find('Canvas/safe_node/LMSlots_PrizePool_1').getComponent("LMSlots_PrizePool_Base");
        prizepool.PausePool([{prizeType:0,pauseNum:poolList[0]},{prizeType:1,pauseNum:poolList[1]},
            {prizeType:2,pauseNum:poolList[2]},{prizeType:3,pauseNum:poolList[3]}]);
    },

    //复位奖池(继续滚动)
    resetJackpot(){
        let prizepool = cc.find('Canvas/safe_node/LMSlots_PrizePool_1').getComponent("LMSlots_PrizePool_Base");
        prizepool.ResumePausePool();
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },
    // update (dt) {},
});
