// Learn life-cycle callbacks:
//  - https://docs.cocos.com/creator/manual/en/scripting/life-cycle-callbacks.html

cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        _isFiveGem:false,   // 当前为5个宝石触发bonus
        _isFreeGame:false,

    },

    start () {

    },

    Init(top,bottom){
        this._node_banner = cc.find("node_banner", this.node);


        this._super(top,bottom);
    },

    RegisterEvent:function(){
        this._super();

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,this.onEventTotalbetUpdated,this)// 押注额改变
    },

    // 断线重连
    async ReconnectShow(){
        // this._super();

        this.onEventTotalbetUpdated();

        if(cc.vv.gameData.GetBonusState()){

            await new Promise(async (sucess, failed)=> {
                cc.vv.gameData.GetBonusScript().enterBonusGame(sucess);
            })
        }

        if (cc.vv.gameData.GetTotalFree() > 0){
            this.ShowGameview(true);
            if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() == 0){
                await this.CheckExitFreeGame();
            }
        } else {
            this.ShowGameview(false);
        }
        //   退出免费之类的



        this._topScript.StopMove()
        this._bottomScript.CanDoNextRound();
    },

    onMsgSpine(msg){
        if(cc.vv.gameData.IsBonusGame()){
            cc.vv.gameData.GetBonusScript().onMsgSpine(msg)
        } else {
            this._super(msg);
        }
    },

    SetSlotsResult:function(cards){
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col;
        let reelResults = [];
        for(let i = 0;i < cards.length; i++){
            let row = Math.floor(i / acRow);
            let col = i % this._col;
            //配置中有没有这个元素
            if(this._cfg.symbol[cards[i]]){
                let res = {};
                res.sid = cards[i]; //符号id

                let infoData = cc.vv.gameData.GetBonusInfo();
                for (let key in infoData){
                    let idx = Number(key.substring("idx_".length));
                    if(idx === i+1){
                        res.data = infoData[key];
                    }
                }

                if(!reelResults[col]) reelResults[col] = [];
                reelResults[col].unshift(res);
            }
        }

        for(let i = 0; i < this._reels.length; i++){
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    SetReelStateInfo:function(cards){
        if(cc.vv.gameData.IsBonusGame()){
            return;
        }
        if (!this._cfg.reelStateInfo) {
            return;
        }
        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            let id = cards[i]
            let col = i % this._col
            if(!reelResults[col]) reelResults[col] = []
            reelResults[col].push(id)
        }

        for (let info of this._cfg.reelStateInfo) {
            let stateInfo = Global.copy(info);
            stateInfo.isStop = false
            stateInfo.isAnt = false

            let triggerCount = stateInfo.mini
            let countsConfig = Global.copy(stateInfo.counts);
            let haveCount = 0

            for(let i = 0; i < reelResults.length; i++){
                let item = this._reels[i]
                let reelRes = reelResults[i]
                stateInfo.isStop = false
                stateInfo.isAnt = false
                if (haveCount >= triggerCount-1 && stateInfo.counts[i] > 0) {  //满足条件 需要播放加速框
                    stateInfo.isAnt = true
                }

                if (i === 2){
                    stateInfo.symbolStopSound = "scatterSmart_stop_2";
                } else if (i === 3){
                    stateInfo.symbolStopSound = "scatterSmart_stop_3";
                } else {
                    stateInfo.symbolStopSound = info.symbolStopSound;
                }

                let reelCountOfID = reelRes.reduce((a, v) => stateInfo.id.includes(v) ? a + 1 : a + 0, 0);
                haveCount +=  reelCountOfID
                countsConfig.shift()
                let remainingCount = (countsConfig.length > 0 ? countsConfig.reduce((x,y)=>x+y):0) + haveCount
                if (reelCountOfID > 0 && remainingCount >= triggerCount) {  //满足条件 播放停止动画和停止音效
                    stateInfo.isStop = true
                }
                item.AddReelStateInfo(Global.copy(stateInfo))
            }
        }
    },

    StartMove(){
        if(cc.vv.gameData.IsBonusGame()){
            cc.vv.gameData.GetBonusScript().StartMove()
        } else {
            this._super();
            Global.SlotsSoundMgr.playNormalBgm()
        }
    },

    StopMove(){
        if(cc.vv.gameData.IsBonusGame()){
            cc.vv.gameData.GetBonusScript().StopMove()
        } else {
            this._super();
        }
    },

    OnReelBounsActionDeep(colIdx){
        this._super(colIdx);
        for(let row = 0; row < this._row; row++){
            let syc = this._reels[colIdx].GetSymbolByRow(row)
            if(this._cfg.gemIdList.includes(syc.GetShowId())){
                Global.SlotsSoundMgr.playEffect("symbol_coin_land");
                cc.tween(syc.node)
                    .to(0.2,{scale:1.2},{easing:"backOut"})
                    .to(0.05,{scale:1},)
                    .start()
            }

            if(syc.GetShowId() === 3){
                Global.SlotsSoundMgr.playEffect("retrigger_land");
            }
        }
    },

    OnSpinEnd(){
        this.onSpinEndAction();

    },

    async onSpinEndAction(){

        // 显示中奖路线
        this.ShowWinTrace()
        // 显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()){
            nTotal = cc.vv.gameData.GetFreeWinCoin()
        }
        await new Promise((sucess, failed)=>{
            this.ShowBottomWin(nWin,nTotal,true,sucess)
        });


        // 触发免费
        let freeInfo = this._gameInfo.freeResult.freeInfo;
        if (freeInfo && freeInfo.freeCnt > 0){

            await this.CheckEnterFreeGame();
        }

        // 触发小游戏
        if(this._gameInfo.bonusGame && this._gameInfo.bonusGame.start){
            await this.CheckTriggerBonusGame();
        }


        // 免费结束
        if(this._gameInfo.allFreeCnt > 0 && this._gameInfo.freeCnt == 0){
            await this.CheckExitFreeGame();
        }

        this.CanDoNextRound();
    },


    // 检查触发免费
    async CheckEnterFreeGame(){
        return new Promise(async (sucess, failed)=>{

            Global.SlotsSoundMgr.playEffect("bell");
            for (let id of this._gameInfo.freeResult.freeInfo.idxs) {
                let symbol = this.GetSymbolByIdx(id)
                if(symbol){
                    symbol.playTriggerAnimation()
                }
            }
            await this.awaitTime(1.5);

            if( this._gameInfo.freeCnt === this._gameInfo.allFreeCnt){ // 首次
                this.Backup();

                await cc.vv.gameData.GetPopupScript().showFirstGainFree();
                cc.vv.gameData.GetPopupScript().playFreeQpAnim();

                await this.awaitTime(1.3);
                this.ShowGameview(true)
            } else {
                let times = this._gameInfo.freeResult.freeInfo.freeCnt;
                await cc.vv.gameData.GetPopupScript().showAgainGainFree(times);

                await this.awaitTime(0.8);
            }

            sucess();
        });
    },

    // 免费结束
    async CheckExitFreeGame() {
        return new Promise(async (sucess, failed) => {
            await cc.vv.gameData.GetPopupScript().showEndFree(cc.vv.gameData.GetFreeWinCoin());
            cc.vv.gameData.GetPopupScript().playFreeQpAnim();
            await this.awaitTime(1.3);

            this.Resume();
            this.ShowGameview(false);
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playNormalBgm()

            await this.awaitTime(0.5);
            let nWin = cc.vv.gameData.GetFreeWinCoin();
            let nTotal = nWin;
            await new Promise((sucess, failed)=>{
                this.ShowBottomWin(nWin,nTotal,true,sucess)
            });
            sucess();
        })
    },

    // 触发小游戏
    async CheckTriggerBonusGame(){
        return new Promise(async (sucess, failed) => {
            Global.SlotsSoundMgr.playEffect("bell");
            await this.awaitTime(1);

            await cc.vv.gameData.GetPopupScript().playTriBonusAnim1();
            cc.vv.gameData.GetPopupScript().playBonusQpAnim();
            await this.awaitTime(0.5);

            cc.vv.gameData.GetBonusScript().triBonusGame(sucess)
        })
    },

    playGameBgm(){
        if(this._isFreeGame){
            Global.SlotsSoundMgr.playBgm('free_bgm');
        } else {
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playNormalBgm();
        }
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview:function(bFree){
        this._isFreeGame = bFree;
        if(bFree){
            Global.SlotsSoundMgr.playBgm('free_bgm')

            let total = cc.vv.gameData.GetTotalFree()
            let rest = cc.vv.gameData.GetFreeTime()

            //显示免费次数
            this._bottomScript.ShowFreeModel(true,total-rest,total)
            let nTotal = cc.vv.gameData.GetFreeWinCoin()
            this._bottomScript.SetWin(nTotal)

        }
        else{
            this._bottomScript.ShowFreeModel(false)
        }
        //可能还需要显示免费背景图
        let normalBg = cc.find("Canvas/safe_node/spr_bg_normal");
        let normalFree = cc.find("Canvas/safe_node/spr_bg_free");
        if(normalFree){ //存在免费游戏背景才执行下面的逻辑
            if(normalBg){
                normalBg.active = !bFree
            }
            normalFree.active = bFree
        }
    },

    // 押注额改变
    onEventTotalbetUpdated(){
        let node_4 = cc.find("node_4",this._node_banner);
        let node_5 = cc.find("node_5",this._node_banner);
        let spine_change = cc.find("spine_change",this._node_banner);

        let curBet = cc.vv.gameData.GetBetIdx();
        let minBet = cc.vv.gameData.GetChangeNumBet();

        if(!this._isFiveGem && curBet < minBet){
            Global.SlotsSoundMgr.playEffect("bet_change");
            this._isFiveGem = true
            spine_change.active = true;
            spine_change.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
            node_4.active = false;
            node_5.active = true;
        }else if (this._isFiveGem && curBet >= minBet){
            Global.SlotsSoundMgr.playEffect("bet_change");
            this._isFiveGem = false
            spine_change.active = true;
            spine_change.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
            node_4.active = true;
            node_5.active = false;
        }
    },
/*
    GetBonusData(idx){
        let infoData = cc.vv.gameData.GetBonusInfo();
        return infoData[idx];
    },*/

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

});
